using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests.LoyaltyDiscount;

public sealed class CalculatePayableTotalAcceptanceTests
{
    [Theory]
    [InlineData(LoyaltyTier.Green, 4_999, 4_750)]    // 5%: 249.95 floored to 249
    [InlineData(LoyaltyTier.Green, 5_000, 4_700)]    // threshold in upper band: 6%
    [InlineData(LoyaltyTier.Green, 19_999, 18_799)]  // 6%: 1199.94 floored
    [InlineData(LoyaltyTier.Green, 20_000, 18_400)]  // 8%
    [InlineData(LoyaltyTier.Gold, 10_000, 9_200)]    // 8%
    [InlineData(LoyaltyTier.Gold, 20_000, 18_000)]   // 10%
    [InlineData(LoyaltyTier.Platinum, 4_999, 4_550)] // 9%: 449.91 floored
    [InlineData(LoyaltyTier.Platinum, 10_000, 9_000)] // 10%
    [InlineData(LoyaltyTier.Platinum, 20_000, 18_000)] // capped at 10 (12)
    [InlineData(LoyaltyTier.Green, 0, 0)]
    public void CustomersPayTheApprovedLoyaltyTotal(LoyaltyTier tier, int subtotalCents, int expectedPayableCents)
    {
        Assert.Equal(expectedPayableCents, new CalculatePayableTotal().For(subtotalCents, tier));
    }
}
